mapper.select:
select activity_id
from corgi_activity_topic
where topic = #{topic}
order by `weight` desc
    limit #{start}, #{size}

mapper.delete:
delete from corgi_activity_message
where to_user_id = #{message.toUserId}

    and `comment_id` = #{message.commentId}


    and `activity_id` = #{message.activityId}


    and `from_user_id` = #{message.fromUserId}


    and `message_type` = #{message.messageType}

mapper.select:
select count(1)
from corgi_activity_message
where to_user_id = #{message.toUserId}

    and activity_id = #{message.activityId}


    and from_user_id = #{message.fromUserId}


    and message_type = #{message.messageType}


    and comment_id = #{message.commentId}


    and is_read = #{message.isRead}

mapper.delete:
delete
from corgi_activity_message
where to_user_id = #{userId}
  and `time` <= #{time}

mapper.update:
update corgi_activity_message
set is_read = '1'
where to_user_id = #{userId}

update corgi_activity_message
set is_read = '1'
where to_user_id = #{userId}
  and message_type = #{type}

